'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var logcdf = factory( 1.0, 1.0 );
	t.strictEqual( typeof logcdf, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 1.0, 1.0 );
	y = logcdf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, 1.0 );
	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( 1.0, NaN );
	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, NaN );
	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, NaN );
	y = logcdf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a valid `mu` and `lambda`, the function returns a function which returns `0` when provided `+infinity` for `x`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 1.0, 0.0 );
	y = logcdf( PINF );
	t.strictEqual( y, 0.0, 'returns expected value' );

	logcdf = factory( 1.0, 1.0 );
	y = logcdf( PINF );
	t.strictEqual( y, 0.0, 'returns expected value' );

	t.end();
});

tape( 'if provided a valid `mu` and `lambda`, the function returns a function which returns `-infinity` when provided `-infinity` for `x`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 1.0, 0.0 );
	y = logcdf( NINF );
	t.strictEqual( y, NINF, 'returns expected value' );

	logcdf = factory( 1.0, 1.0 );
	y = logcdf( NINF );
	t.strictEqual( y, NINF, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `mu`, the created function always returns `NaN`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 0.0, 1.0 );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( -1.0, 1.0 );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, 1.0 );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a negative `lambda`, the created function always returns `NaN`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 0.0, -1.0 );

	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	y = logcdf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( 0.0, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( PINF, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NINF, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	logcdf = factory( NaN, NINF );
	y = logcdf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if `lambda` equals `0`, the created function evaluates a degenerate distribution centered at `mu`', function test( t ) {
	var logcdf;
	var y;

	logcdf = factory( 2.0, 0.0 );

	y = logcdf( 2.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = logcdf( 3.0 );
	t.strictEqual( y, 0.0, 'returns expected value' );

	y = logcdf( 1.0 );
	t.strictEqual( y, NINF, 'returns expected value' );

	t.end();
});

tape( 'the function evaluates the logcdf for `x` given parameters `mu` and `lambda`', function test( t ) {
	var expected;
	var lambda;
	var logcdf;
	var mu;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.x;
	mu = data.mu;
	lambda = data.lambda;
	for ( i = 0; i < x.length; i++ ) {
		logcdf = factory( mu[i], lambda[i] );
		y = logcdf( x[i] );
		if ( y === expected[i] ) {
			t.strictEqual( y, expected[i], 'x: '+x[i]+', mu:'+mu[i]+', lambda: '+lambda[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.ok( isAlmostSameValue( y, expected[ i ], 70 ), 'within tolerance. x: '+x[ i ]+'. mu: '+mu[i]+'. lambda: '+lambda[i]+'. y: '+y+'. E: '+expected[ i ]+'.' );
		}
	}
	t.end();
});
